import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"AI, email & messaging API setup","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/ai-messaging-setup.md","filePath":"integrations/ai-messaging-setup.md"}'),d={name:"integrations/ai-messaging-setup.md"};function n(r,e,s,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-email-messaging-api-setup" tabindex="-1">AI, email &amp; messaging API setup <a class="header-anchor" href="#ai-email-messaging-api-setup" aria-label="Permalink to &quot;AI, email &amp; messaging API setup&quot;">​</a></h1><p>Source-reviewed v0.7.26. The following identifiers occur in server adapter code. They are not a complete activation contract or confirmation of real delivery.</p><table tabindex="0"><thead><tr><th>Service</th><th>Server-side configuration identifiers</th></tr></thead><tbody><tr><td>Gemini</td><td><code>GEMINI_API_KEY</code></td></tr><tr><td>Resend</td><td><code>RESEND_API_KEY</code>, <code>RESEND_FROM</code> or <code>SMTP_FROM</code></td></tr><tr><td>SendGrid</td><td><code>SENDGRID_API_KEY</code>, <code>SMTP_FROM</code></td></tr><tr><td>HTTP email relay</td><td><code>SMTP_HTTP_RELAY_URL</code>, optional <code>SMTP_PASS</code>, <code>SMTP_HOST</code>, sender configuration</td></tr><tr><td>Twilio SMS</td><td><code>TWILIO_ACCOUNT_SID</code>, <code>TWILIO_AUTH_TOKEN</code>, <code>TWILIO_FROM_NUMBER</code> or <code>TWILIO_PHONE_NUMBER</code></td></tr><tr><td>WhatsApp delivery</td><td><code>WHATSAPP_PHONE_NUMBER_ID</code>, <code>WHATSAPP_ACCESS_TOKEN</code></td></tr><tr><td>Meta inbound webhook</td><td><code>META_WEBHOOK_VERIFY_TOKEN</code>, <code>META_APP_SECRET</code></td></tr></tbody></table><h2 id="setup-and-acceptance" tabindex="-1">Setup and acceptance <a class="header-anchor" href="#setup-and-acceptance" aria-label="Permalink to &quot;Setup and acceptance&quot;">​</a></h2><ol><li>Obtain the AI key from Google AI Studio or an approved Gemini project; review permitted model use, privacy and spending. Keep it server-only. Test synthetic conversations and human takeover; do not send unnecessary passenger contact data or permit unauthorized actions.</li><li>For email use one approved provider and verify sender/domain, delivery and bounce handling. Configure the sender address explicitly. A bare SMTP host is not native SMTP delivery in this adapter; an approved HTTP relay is required for the relay path.</li><li>For SMS obtain an approved Twilio sender and account credentials. Test recipient consent, opt-out and delivery failures. For WhatsApp use an approved Meta Business account, sender phone ID and access token, with approved message templates as applicable.</li><li>For inbound Meta events the source mounts GET verification and signed POST at <code>/api/v1/webhooks/messaging/:channel</code> (channel: whatsapp, meta_messenger or instagram). Register only after the actual public callback is approved and accessible. Verify HMAC signature over raw request body, account-to-tenant mapping, accepted event envelope and duplicate protection. Do not disable signature checks.</li><li>Persistent delivery history and retries exist, but real provider acceptance is separate. Confirm that opt-out is respected, retries do not duplicate deliveries, and failures never appear as sent. No automatic public intake or provider delivery is authorized by this guide.</li></ol><p>Catalog credential labels may differ from actual adapter variables; use installed runtime code and approved deployment instructions, not conceptual names from the integration catalog. Do not use unofficial WhatsApp Web automation.</p>',6)])])}const _=t(d,[["render",n]]);export{m as __pageData,_ as default};
